import React from 'react';

export default function PaymentCard({ amount = '100.00', momoNumber = '0595655042', onUpload }) {
  return (
    <div className="card payment-card glass-form">
      <h3>Payment Instructions</h3>
      <p>Send payment to MoMo number: <strong>{momoNumber}</strong></p>
      <p>Amount: <strong>{amount}</strong></p>
      <p>After payment, upload proof below for admin approval.</p>
      <div style={{ marginTop: 12 }}>
        {onUpload && <div>{onUpload()}</div>}
      </div>
    </div>
  );
}
